-- Conteúdo inicial da base de conhecimento. Pode ser editado ou despublicado no CMS.
INSERT IGNORE INTO categories (title, uri, description, type) VALUES
 ('Primeiros passos', 'ajuda-primeiros-passos', 'Conta, contexto pessoal e empresa.', 'help'),
 ('Atendimento', 'ajuda-atendimento', 'Como pedir ajuda e acompanhar chamados.', 'help'),
 ('Assinatura', 'ajuda-assinatura', 'Plano, limites e situação.', 'help'),
 ('Administração do CMS', 'ajuda-cms', 'Guias para a equipe Realizze.', 'help');

INSERT IGNORE INTO posts (category, post_type, title, uri, subtitle, content, status, post_at)
SELECT c.id, 'help', a.title, a.uri, a.subtitle, a.content, 'published', NOW() FROM (
  SELECT 'ajuda-primeiros-passos' folder, 'Como trocar entre pessoal e empresa' title, 'alternar-pessoal-empresa' uri, 'Veja como escolher em qual contexto você está trabalhando.' subtitle, '<p>O Realizze separa suas finanças pessoais das finanças de cada empresa.</p><h2>Como trocar</h2><ol><li>No menu lateral do aplicativo, abra o seletor no topo.</li><li>Escolha o contexto pessoal ou uma das suas empresas.</li></ol><p>Os dados mostrados passam a ser somente os do contexto escolhido.</p>' content
  UNION ALL SELECT 'ajuda-atendimento', 'Como abrir um chamado', 'abrir-chamado', 'Peça ajuda à equipe diretamente pelo aplicativo.', '<ol><li>Clique na aba <strong>Suporte</strong>, na lateral direita da tela.</li><li>Escolha <strong>Atendimento</strong>, o tipo de ajuda e o módulo.</li><li>Clique em <strong>Abrir chamado</strong>, preencha assunto, categoria e mensagem.</li><li>Envie. Você recebe um protocolo no formato RZ-000123.</li></ol><p>Não envie senhas nem dados completos de cartão.</p>'
  UNION ALL SELECT 'ajuda-atendimento', 'Como acompanhar e responder um chamado', 'acompanhar-chamado', 'Consulte a situação e continue a conversa com a equipe.', '<p>Em <strong>Suporte &gt; Meus chamados</strong> você vê todos os seus chamados e a situação de cada um.</p><p>Abra um chamado para ler o histórico, responder e anexar arquivos. Quando houver resposta, uma notificação aparece na aba Suporte.</p>'
  UNION ALL SELECT 'ajuda-atendimento', 'Quais arquivos posso anexar', 'anexos-permitidos', 'Formatos e limites aceitos nos chamados.', '<p>Você pode anexar imagens JPG, PNG, GIF ou WebP, arquivos PDF e arquivos de texto.</p><ul><li>Até 10 MB por arquivo.</li><li>Até 5 arquivos por mensagem.</li></ul><p>Somente quem tem acesso ao chamado consegue baixar os anexos.</p>'
  UNION ALL SELECT 'ajuda-atendimento', 'Como encerrar ou reabrir um chamado', 'encerrar-reabrir-chamado', 'O que fazer quando o problema foi resolvido ou voltou.', '<p>Quando a equipe marca o chamado como resolvido, você pode <strong>confirmar a resolução</strong>, que encerra o chamado, ou <strong>reabrir</strong>, que o devolve à fila.</p><p>Depois de resolvido, também é possível avaliar o atendimento.</p>'
  UNION ALL SELECT 'ajuda-assinatura', 'Onde vejo meu plano', 'ver-meu-plano', 'Consulte plano, situação e limites da sua assinatura.', '<p>Abra a aba <strong>Suporte</strong> e escolha <strong>Minha assinatura</strong>. A página mostra o plano, a situação, o ciclo, a renovação e os limites.</p><p>Em empresas, somente o responsável vê o valor contratado.</p>'
  UNION ALL SELECT 'ajuda-cms', 'Como publicar uma página ou um artigo', 'publicar-conteudo-cms', 'Do rascunho ao site, com SEO automático.', '<ol><li>Em <strong>Site</strong>, abra Páginas ou Conteúdos e crie um novo item.</li><li>Escreva o título, o resumo e o conteúdo.</li><li>Clique em <strong>Publicar</strong>. Com data futura, o artigo fica agendado.</li></ol><p>Título, descrição, URL e imagem social são gerados automaticamente. Para ajustar, use <strong>Personalizar SEO</strong>.</p>'
  UNION ALL SELECT 'ajuda-cms', 'Como alterar preços de um plano', 'alterar-precos-plano', 'Reajustes não mudam contratos existentes.', '<p>Em <strong>Plataforma &gt; Planos e preços</strong>, abra o plano, altere os valores e informe o motivo.</p><p>O histórico é preservado e as assinaturas existentes mantêm o valor contratado. O site passa a mostrar o novo preço.</p>'
  UNION ALL SELECT 'ajuda-cms', 'Como atender chamados', 'atender-chamados-cms', 'Fila, respostas, notas internas e situação.', '<p>Em <strong>Atendimento &gt; Fila de atendimento</strong>, os chamados aparecem por prioridade. Abra um chamado para responder, atribuir, registrar tempo e alterar a situação.</p><p>Marque <strong>Nota interna</strong> para escrever algo que o cliente não vê.</p>'
) a JOIN categories c ON c.uri = a.folder;
